    switch (self) {
      case StoreError_NotInitialized():
        sse_encode_i_32(0, serializer);
      case StoreError_AlreadyInitialized():
        sse_encode_i_32(1, serializer);
      case StoreError_Io(field0: final field0):
        sse_encode_i_32(2, serializer);
        sse_encode_String(field0, serializer);
      case StoreError_Serialization(field0: final field0):
        sse_encode_i_32(3, serializer);
        sse_encode_String(field0, serializer);
      case StoreError_EncryptionKeyNotSet():
        sse_encode_i_32(4, serializer);
      case StoreError_InvalidKeyLength(field0: final field0):
        sse_encode_i_32(5, serializer);
        sse_encode_usize(field0, serializer);
      case StoreError_Encryption():
        sse_encode_i_32(6, serializer);
      case StoreError_InvalidCiphertext():
        sse_encode_i_32(7, serializer);
      case StoreError_UnsupportedEncryptionVersion(field0: final field0):
        sse_encode_i_32(8, serializer);
        sse_encode_u_8(field0, serializer);
      case StoreError_AuthenticationFailed():
        sse_encode_i_32(9, serializer);
      case StoreError_InvalidCounterValue(field0: final field0):
        sse_encode_i_32(10, serializer);
        sse_encode_String(field0, serializer);
    }
  }

  @protected
  void sse_encode_stored_item(StoredItem self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.key, serializer);
    sse_encode_list_prim_u_8_strict(self.value, serializer);
    sse_encode_bool(self.encrypted, serializer);
    sse_encode_opt_box_autoadd_i_64(self.expiresAtMs, serializer);
  }

  @protected
  void sse_encode_stored_value(StoredValue self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_prim_u_8_strict(self.value, serializer);
    sse_encode_bool(self.encrypted, serializer);
    sse_encode_opt_box_autoadd_i_64(self.expiresAtMs, serializer);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_i_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putInt32(self);
  }
